import{_ as s,c as t,o as n,j as a,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易集傳序","description":"漢上易傳 - 周易集傳序","frontmatter":{"title":"周易集傳序","description":"漢上易傳 - 周易集傳序"},"headers":[],"relativePath":"classics/hanshang/001.md","filePath":"classics/hanshang/001.md"}'),l={name:"classics/hanshang/001.md"};function c(o,e,i,d,p,h){return n(),t("div",null,[...e[0]||(e[0]=[a("h1",{id:"周易集傳序",tabindex:"-1"},[r("周易集傳序 "),a("a",{class:"header-anchor",href:"#周易集傳序","aria-label":"Permalink to “周易集傳序”"},"​")],-1),a("p",null,"漢上易傅四部叢刊續編經部上海涵芬樓景印北平圖書館藏宋刊本闕卷，以汲古閣影宋鈔本配補。原書板高二十二公分，寬十五公分。",-1),a("p",null,"聖人觀陰陽之變而立卦，效天下之動而生爻。變動之別，其傳有五：曰動爻，曰卦變，曰互體，曰五行，曰納甲。而卦變之中又有變焉：一三五，陽也；二四六，陰也。天地相函，坎離相交，謂之位。七，八者，陰陽之稚；六、九者，陰陽之究。稚，不變也，究則變焉，謂之策。七、八、九、六，或得或失，雜而成文，謂之爻。昔周人掌三易之法，一曰連山，二曰歸藏，三曰周易。七、八者，連山、歸藏也；六、九者，周易也。經實備之。策三變而成爻，爻六變而成位。變者以不變為體，不變者以變者為用。四象並行，八卦交錯，而天地萬物之情可見矣。其在繫辭曰：爻象動乎內，吉凶見乎外。又曰：道有變動，故曰爻。此見於動爻者也。乾生三男，坤生三女。乾交乎坤，自姤至剝；坤交乎乾，自復至夬。十有二卦，謂之闢卦。坎、離、震、兌，謂之四正。四正之卦，分主四時。十有二卦，各主其月。乾貞於子而左行，坤貞於未而右行，左右交錯，六十卦周天而復陰。陽之升降，四時之消息，天地之盈虛，萬物之盛衰鹹系焉。其在易之復曰七日來複。象曰至，日在。革，曰先王以治歷明時。在說卦曰：震，東方也。巽，東南也。離，南方之卦也。兌，正秋也。乾，西北之卦也。坎，正北方之卦也。艮，東北之卦也。此見於卦變者也。乾生者四卦，坤生者四卦，八卦變復生六十二。坎、離，肖乾坤者也。大過、小過、頤、中孚，肖坎離者也。故乾、坤不動，而坎、離四卦亦莫之動。其略陳於雜卦，其詳具於六十四卦之彖，所謂辨是與非者也。此卦變之中又有變焉者也。一卦含四卦，四卦之中復有變動，上下相揉，百物成象。其在易，則離、震合而有頤，坤、離具而生坎。在繫辭，則罔罟取離，耒耨取益，為市取噬嗑，舟楫取渙，服乘取隨，門柝取豫，杵臼取小過，弧矢取睽，棟宇取大壯，棺槨取大過，書契取夬。又曰：八卦相蕩。又曰：六爻相雜，唯其時物也。又曰：雜物撰德。此見於互體者也。一生水而成六，二生火而成七，三生木而成八，四生金而成九，五生土而成十。生於陽者成於陰，三天兩地也。生於陰者成於陽，兩地而三天也。天以三兼二，地以二兼三，五位相得，合而為五十。其在繫辭曰：",-1),a("p",null,"天一地二，天三地四，天五地六，天七地八，天九地十。在說卦曰：巽為木，坎為水，離為火。此見於五行者也。乾納甲壬，坤納乙癸，震納庚，巽納辛，坎納戊，離納己，艮納丙，兌納丁。庚、戊、丙三者，得於乾者也。辛、己、丁三者，得於坤者也。始於甲乙，終於壬癸，而天地五十五數具焉。其在易之蠱曰：先甲三日，後甲三日。在巽曰先庚三日，後庚三日。在離，曰：己日乃孚。在繫辭曰：懸象著明，莫大於日月。此見於納甲者也。凡此五者之變，自一二三四言之謂之數，自有形無形言之謂之象，自推考象數言之謂之佔。聖人無不該也，無不徧也，隨其變而言之謂之辭。辭也者，所以明道也。故辭之所指，變也，象數也，佔也，無不具焉。是故可以動，可以言，可以制器，可以卜筮。蓋不如是，不足以明道之變動而盡夫時中也。故曰繫辭焉而命之，動在其中矣。夫易廣矣大矣，其遠不可御矣。然不越乎陰陽二端，其究則一而巳矣。一者，天地之根本也，萬物之權輿也。陰陽，動靜之源也，故謂之太極。學至於此止矣。卦可遺也，爻可忘也，五者之變，反於一也。是故聖人之辭，因是而止矣。",-1)])])}const f=s(l,[["render",c]]);export{_ as __pageData,f as default};
